it('answers list_sessions with formatted summaries when listFor succeeds', async () => {
  const summaries: SessionSummary[] = [
    {
      sessionId: 's1',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-01T00:05:00.000Z'),
      entryCount: 2,
    },
  ];
  const store = mockStore({listFor: jest.fn(async () => summaries)});
  const h = harness([], {sessionStore: store, history: {enabled: true}});
  await h.send({type: 'list_sessions'});
  expect(h.frames()).toEqual(['session_list [s1 2026-01-01T00:05:00.000Z]']);
});

it('answers SERVER_ERROR and logs when listFor throws', async () => {
  const store = mockStore({
    listFor: jest.fn(async () => {
      throw new Error('database offline');
    }),
  });
  const h = harness([], {sessionStore: store, history: {enabled: true}});
  await h.send({type: 'list_sessions'});
  expect(h.frames()).toEqual(['error SERVER_ERROR']);
});

